function fill(){if(displayedProperty!==key){displayedProperty=key;helperText=idleStatus(current());}dialog?.querySelectorAll('[data-property]').forEach(tab=>{const active=tab.dataset.property===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});const e=current();if(!e)return;for(const field of ['address','community','aliases','addresses','mode','searchPurpose'])dialog.querySelector('[name='+field+']').value=e.config[field]||'';dialog.querySelector('[name=enabled]').checked=!!e.config.enabled;dialog.querySelector('[name=transactionsEnabled]').checked=!!e.config.transactionsEnabled;dialog.querySelector('[name=notifyDown]').checked=e.config.notifyDown!==false;for(const [field] of E.conditionFields)for(const side of ['Min','Max'])dialog.querySelector('[name='+field+side+']').value=e.config.criteria?.[field+side]??'';dialog.querySelector('[name=buildingType]').value=e.config.criteria?.buildingType||'';dialog.querySelector('[name=floorMatch]').value=e.config.criteria?.floorMatch||'contained';dialog.querySelector('[name=searchPurpose] option[value=""]').textContent='依庫存（'+(e.config.inventoryPurpose||'尚未確認')+'）';purposeHint();grow();dialog._savedForm=formSnapshot();renderResults();loadState(e.config.id).then(()=>{if(current()?.key===e.key){helperText=idleStatus(e);renderResults();}}).catch(error=>{helperText=error.message;renderResults();});}
async function saveConfig(){const e=current();if(!e)return;const saveButton=dialog.querySelector('#imSave'),notice=dialog.querySelector('#imSaveNotice');saveButton.disabled=true;saveButton.textContent='儲存中…';notice.textContent='正在儲存設定…';notice.dataset.state='saving';const config={...e.config};for(const f of ['address','community','aliases','addresses','mode','searchPurpose'])config[f]=dialog.querySelector('[name='+f+']').value.trim();config.enabled=dialog.querySelector('[name=enabled]').checked;try{config.transactionsEnabled=dialog.querySelector('[name=transactionsEnabled]').checked;config.notifyDown=dialog.querySelector('[name=notifyDown]').checked;config.criteria=E.criteria({floorMatch:dialog.querySelector('[name=floorMatch]').value,buildingType:dialog.querySelector('[name=buildingType]').value,...Object.fromEntries(E.conditionFields.flatMap(([f])=>['Min','Max'].map(side=>[f+side,dialog.querySelector('[name='+f+side+']').value])))});if(config.enabled||config.transactionsEnabled)demands(config);if(config.enabled&&config.mode==='building'&&!E.location(config.address)?.building)throw Error('同大樓追蹤請填寫含門牌號碼的地址');for(const a of config.addresses.split(/[\n,，、]/).filter(Boolean)){const loc=E.location(a),home=E.location(config.address);if(!loc?.building||loc.city!==home?.city||loc.district!==home?.district)throw Error('其他門牌需完整填寫，且位於同縣市行政區');}const criteriaChanged=JSON.stringify(config.criteria)!==JSON.stringify(e.config.criteria||{});const scopeChanged=['address','community','aliases','addresses','mode'].some(f=>(config[f]||'')!==(e.config[f]||''));if(scopeChanged){config.buildingDecisions={};config.ownIds=[];config.excludedGroups=[];}const changed=scopeChanged||criteriaChanged||config.searchPurpose!==e.config.searchPurpose;if(!config.id||changed)config.id=crypto.randomUUID();const old=e.c.inventoryWatch;e.c.inventoryWatch={...old,[e.slot]:config};if(!persist()){e.c.inventoryWatch=old;throw Error('設定未保存');}if(changed&&!scopeChanged&&e.config.id){const prior=await loadState(e.config.id);if(prior)await updateState(config.id,()=>({...prior,events:[],baselines:Object.fromEntries(Object.entries(prior.baselines||{}).filter(([id])=>id.startsWith('moi'))),scans:{},records:Object.fromEntries(Object.entries(prior.records||{}).map(([id,p])=>[id,{...p,missingScans:0,verifiedScan:undefined}]))}));}refreshDetailChecks();window.render?.();helperText=changed?'範圍已變更，將重新建立基準。':'設定已保存。';notice.textContent='已儲存';notice.title='在售清單與每日自動找案會套用這組條件，成交行情不受影響。';notice.dataset.state='success';saveButton.textContent='已儲存';fill();dialog.querySelector('.im-config').open=false;showToast('設定已儲存');await sync().catch(error=>{notice.textContent='設定已儲存；自動找案尚未同步：'+error.message;notice.dataset.state='error';showToast(notice.textContent,'error');});await tick(true);}catch(error){helperText=error.message;notice.textContent='儲存未完成：'+error.message;notice.dataset.state='error';renderResults();}finally{saveButton.disabled=false;saveButton.textContent='儲存設定';}}
async function search(retry=false){const e=current();if(!e?.config.enabled){helperText='請先儲存並開啟此庫存追蹤。';renderResults();return;}dialog.querySelectorAll('.im-disclosures>details').forEach(el=>el.open=false);const button=dialog.querySelector('#imSearch');button.disabled=true;try{await sync();const {job}=await request('progress',{});if(job?.status==='running')throw Error('已有搜尋進行中，請等待完成；不會中斷買方搜尋');retry=retry||(ownsJob(e,job)&&['partial','cancelled'].includes(job.status));if(retry){try{await request('retry',{buyerId:'inventory:'+e.config.id,demands:demands(e.config)});}catch(error){if(!/需求已變更|沒有可重試的未完成搜尋/.test(error.message))throw error;retry=false;await request('inventorySearch',{id:'inventory:'+e.config.id,demands:demands(e.config)});}}else await request('inventorySearch',{id:'inventory:'+e.config.id,demands:demands(e.config)});helperText=retry?'已接續未完成的頁面；保留已取得結果，不重跑已完成部分。':'已開始逐頁搜尋，結果陸續加入；讀到末頁才算完成。';pollProgress();}catch(error){helperText=error.message;}finally{button.disabled=false;renderResults();}}

function confirmExclusion(rows){return new Promise(resolve=>{const modal=document.createElement('dialog');modal.className='im-confirm';modal.setAttribute('aria-labelledby','imConfirmTitle');modal.innerHTML='<h2 id="imConfirmTitle">排除此物件？</h2><p class="im-confirm-count">共 '+rows.length+' 筆刊登</p><p class="im-confirm-name">'+esc(rows[0].title||rows[0].address)+'</p><p>整組疑似同物件會從在售清單隱藏，停止新增、降價及下架提醒。未來符合相同分組條件的刊登也會排除。</p><p>成交行情不受影響，不會刪除資料。誤按可到追蹤設定「恢復全部已排除物件」。</p><footer><button type="button" data-cancel autofocus>取消</button><button type="button" data-confirm>排除 '+rows.length+' 筆刊登</button></footer>';document.body.append(modal);modal.addEventListener('close',()=>{const accepted=modal.returnValue==='confirmed';modal.remove();resolve(accepted);},{once:true});modal.querySelector('[data-cancel]').onclick=()=>modal.close('cancelled');modal.querySelector('[data-confirm]').onclick=()=>modal.close('confirmed');modal.showModal();});}

function mountDisclosurePanels(disclosures){
 const details=[...disclosures.querySelectorAll(':scope>details')];
 details.forEach((item,index)=>{
  const summary=item.querySelector('summary'),panel=document.createElement('div');
  panel.className='im-disclosure-body';panel.id='imDisclosureBody'+index;summary.id='imDisclosureToggle'+index;
  panel.setAttribute('role','region');panel.setAttribute('aria-labelledby',summary.id);summary.setAttribute('aria-controls',panel.id);
  [...item.childNodes].filter(node=>node!==summary).forEach(node=>panel.append(node));
  disclosures.append(panel);
  const update=()=>{panel.hidden=!item.open;summary.setAttribute('aria-expanded',String(item.open));if(item.open)grow();};
  item.addEventListener('toggle',update);new MutationObserver(update).observe(item,{attributes:true,attributeFilter:['open']});update();
 });
}
